const $=s=>document.querySelector(s);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const opening=$('#opening');document.querySelector('header').inert=true;document.querySelector('main').inert=true;const endIntro=()=>{document.querySelector('header').inert=false;document.querySelector('main').inert=false;if(opening.contains(document.activeElement))$('.wordmark').focus();opening.classList.add('done');$('#opening-video').pause();opening.setAttribute('aria-hidden','true');$('#skip-intro').tabIndex=-1};$('#skip-intro').addEventListener('click',endIntro);opening.addEventListener('keydown',e=>{if(e.key==='Escape')endIntro()});if(reduced)endIntro();else {$('#opening-video').play().catch(()=>{});setTimeout(endIntro,8500);}
let motionOff=reduced;function setMotion(off){motionOff=off;document.body.classList.toggle('motion-off',off);$('#motion-toggle').textContent=off?'Motion off':'Motion on';$('#motion-toggle').setAttribute('aria-pressed',String(off));window.dispatchEvent(new CustomEvent('motionchange',{detail:off}));const v=$('#studio-film');if(v){if(off)v.pause();else v.play().catch(()=>{})}}setMotion(reduced);$('#motion-toggle').addEventListener('click',()=>setMotion(!motionOff));
$('#home').addEventListener('pointermove',e=>{if(motionOff||e.pointerType==='touch')return;const x=(e.clientX/innerWidth-.5)*10;const y=(e.clientY/innerHeight-.5)*7;$('#studio').style.transform=`scale(1.05) translate(${x}px,${y}px)`});$('#home').addEventListener('pointerleave',()=>{$('#studio').style.transform='scale(1.04)'});
document.querySelectorAll('[data-target]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.target).scrollIntoView({behavior:motionOff?'instant':'smooth'})));
const film=$('#film-dialog');$('#watch-film').addEventListener('click',()=>{film.showModal();film.querySelector('video').play().catch(()=>{})});document.querySelectorAll('.dialog-close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));film.addEventListener('close',()=>film.querySelector('video').pause());
const skills={ai:['Python','PyTorch','TensorFlow','YOLO','Computer vision','NLP','OCR / ICR','Speech-to-text','Text-to-speech','Qiskit','LLMs','RAG','LangChain','LlamaIndex','Agentic AI','Prompt engineering','Pinecone','Turbopuffer','SGLang','Fine-tuning','Model compression'],infra:['MLflow','H2O MLOps','Kubernetes','Docker','CI/CD','Apache Airflow','Grafana','Prometheus','Edge deployment','Model monitoring','Performance profiling','Distributed systems debugging','AWS','Azure','GCP','SageMaker','Kafka','MQTT','MongoDB','PostgreSQL','Firebase','SCADA'],build:['FastAPI','Django','REST APIs','Node.js','React','Flutter','JavaScript','PHP','Go','Git','Three.js']};function showSkill(key){$('#skill-content').replaceChildren(...skills[key].map(s=>{const n=document.createElement('span');n.textContent=s;return n}));$('#skill-content').setAttribute('aria-labelledby','tab-'+key);document.querySelectorAll('[data-skill]').forEach(b=>{const active=b.dataset.skill===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1})}showSkill('ai');const tabs=[...document.querySelectorAll('[data-skill]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>showSkill(b.dataset.skill));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].click();tabs[n].focus()}})});
const jobs=[['MAR — JUN 2026','AI Engineer','Yosemite MD Solution · Mohali, hybrid','Built RCM automation that processed claims six times faster, voice agents for routine patient and payer calls, and SOAP note transcription. Consolidated three redundant database round trips into one query path: patient records loaded in 600ms, staying under one second at peak.'],['JAN — MAR 2026','Software Developer (Contract)','Independent Contractor · Remote','Stabilised a Node.js edtech platform, built transaction processing and user management for LessPay, and created an OCR pipeline to extract and classify transaction PDF line items for tax planning reports.'],['AUG — DEC 2025','AI/ML Associate (MLOps Engineer)','Aaizel International Technologies · Remote','Trained and deployed multilingual speech-to-text for Indian regional languages with sub-second results. Built MQTT and Kafka radiosonde parsing, satellite-data SCADA validation, real-time face detection with liveness checks, and MLflow/Kubernetes retraining with FastAPI serving.'],['AUG 2024 — JUL 2025','AI Engineer','Sofly Innovation Pvt Ltd · Chandigarh','Built computer vision for drone imagery, improving preprocessing and feature extraction speed by 30%. Compressed edge models, built LangChain and LlamaIndex RAG systems, and improved chatbot answer accuracy by roughly 25% through retrieval and prompting.'],['JAN 2023 — JUL 2024','Co-founder & Technical Lead','Aerwolf Technology','Built flight control software with GPS and IoT integration and automated field mapping for precision agriculture. Designed and proposed a hydrogen fuel cell drone platform to extend endurance beyond battery limits.'],['JUN 2019 — JAN 2023','Founder & Product Developer','Hostsac','Ran a hosting and development agency. Shipped custom websites, Flutter apps and progressive web apps using PHP and Laravel, plus CRM, CMS and SaaS products. Managed servers and CI/CD from first build through deployment and support. Exited the business in 2023.']];jobs.forEach((j,i)=>{const d=document.createElement('details');if(!i)d.open=true;d.innerHTML=`<summary><time>${j[0]}</time><h3>${j[1]}</h3><p>${j[2]}</p></summary><p>${j[3]}</p>`;$('#timeline').append(d)});
const cases={health:{tag:'YOSEMITE MD SOLUTION / MAR–JUN 2026',title:'Less waiting. More care.',context:'Healthcare workflows were slowed by manual claims processing, routine call hand-offs and a 14-second patient records screen.',build:'Built agentic RCM automation, voice agents using speech-to-text and text-to-speech, and SOAP note transcription. Traced three redundant database round trips through a microservice chain to an encrypted table of 40,000+ patient records and consolidated them into one query path.',result:'Claims processed 6× faster than the manual workflow. Patient records loaded in 600ms and stayed under 1 second at peak. The transcription service reduced corrections before doctors signed off.'},speech:{tag:'AAIZEL INTERNATIONAL TECHNOLOGIES / AUG–DEC 2025',title:'Many languages. One fluent system.',context:'A production speech system needed to handle several Indian regional languages with low latency.',build:'Trained and deployed multilingual speech-to-text, with automated retraining using MLflow and Kubernetes and predictions served through FastAPI REST APIs. Also built MQTT/Kafka radiosonde parsing, SCADA validation and real-time face detection with liveness checks.',result:'Speech-to-text returned results in under a second across several Indian regional languages.'},vision:{tag:'SOFLY INNOVATION / AUG 2024–JUL 2025',title:'A different point of view.',context:'Drone imagery applications needed more efficient processing and lower inference latency on edge devices.',build:'Reworked preprocessing and feature extraction in Python and TensorFlow and compressed models for edge deployment. Built conversational AI features using LangChain and LlamaIndex and refined retrieval and prompting.',result:'Preprocessing and feature extraction ran 30% faster. Chatbot answer accuracy improved by roughly 25%.'}};
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const c=cases[b.dataset.project];$('#project-detail').innerHTML=`<p class="eyebrow">${c.tag}</p><h2>${c.title}</h2><h4>The challenge</h4><p>${c.context}</p><h4>The build</h4><p>${c.build}</p><h4>The outcome</h4><p>${c.result}</p><a href="Abhay-Shukla-Resume.pdf" target="_blank" rel="noopener">Read the full resume</a>`;$('#project-dialog').showModal()}));
function localAsk(q){q=q.trim();if(!q)return;const answer=$('#answer');answer.hidden=false;const close=document.createElement('button');close.textContent='Close';close.type='button';close.addEventListener('click',()=>answer.hidden=true);const p=document.createElement('span');const lower=q.toLowerCase();let a;if(/skill|stack|tool|tech|python/.test(lower))a='My toolkit spans Python, PyTorch, TensorFlow, LLMs, RAG, LangChain, LlamaIndex and agentic AI. I deploy with MLflow, Kubernetes and Docker across AWS, Azure and GCP, and build products using FastAPI, Django, Node.js, React and Flutter.';else if(/project|built|work|impact|claim|health/.test(lower))a='At Yosemite MD Solution, I built claims automation that was 6× faster and reduced a patient records load from 14 seconds to 600ms. At Aaizel, I deployed sub-second multilingual speech-to-text. At Sofly, I built drone vision systems and RAG-powered conversational AI. Open a case study below for the details.';else if(/experience|career|journey|company|role/.test(lower))a='I’ve shipped products since founding Hostsac in 2019. I co-founded drone startup Aerwolf in 2023, then worked in AI at Sofly Innovation, Aaizel International Technologies and Yosemite MD Solution, alongside independent full-stack contracts. Explore the timeline for dates and responsibilities.';else if(/educat|degree|university|study|certif/.test(lower))a='I completed B.E. Computer Science & Engineering with Honours in AI and ML at Chandigarh University (2021–2025). My certifications include Anthropic AI Fluency for Builders, AI Fluency Framework and Foundations (2026), and Packt Raspberry Pi and Arduino (2025).';else if(/contact|hire|email|location|remote|relocat|available/.test(lower))a='I’m based in Mohali, Punjab, India and open to remote work and relocation. Reach me at shuklaabhay075@gmail.com or on LinkedIn at linkedin.com/in/abhays02.';else if(/name|who|about|introduc/.test(lower))a='I’m Abhay Shukla, an AI engineer and full-stack developer. I build LLM and RAG systems, agentic automation, computer vision and multilingual speech systems, along with the APIs and MLOps infrastructure they run on.';else a='This guide answers from my resume. Try asking about my experience, projects, skills, education or how to contact me. For something more specific, email shuklaabhay075@gmail.com.';p.textContent=a;const note=document.createElement('small');note.textContent='RESUME GUIDE · LOCAL ANSWERS';note.style.cssText='display:block;margin-top:14px;font-size:8px;letter-spacing:1.5px;color:#9fb4c9';answer.replaceChildren(close,p,note)}$('#ask-form').addEventListener('submit',e=>{e.preventDefault();ask($('#question').value)});document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{$('#question').value=b.dataset.question;ask(b.dataset.question)}));document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#answer').hidden=true});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}$('#share-profile').addEventListener('click',async()=>{if(location.protocol==='file:'||['localhost','127.0.0.1','terminal.local'].includes(location.hostname)){toast('Publish this profile to create a shareable website link.');return}try{await navigator.clipboard.writeText(location.origin+location.pathname);toast('Profile link copied.')}catch{const p=document.createElement('p');p.textContent=location.href;$('#share-profile').parentElement.append(p);toast('Your profile link is shown below.')}});
$('#year').textContent=new Date().getFullYear();function time(){$('#local-time').textContent=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' IST'}time();setInterval(time,60000);
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.metrics,.project,.journey-grid,.credentials,.contact>h2').forEach(n=>{n.classList.add('reveal');observer.observe(n)})}

const siteSettings=fetch('site-config.json').then(r=>r.ok?r.json():({backend:false})).catch(()=>({backend:false}));
let aiEnabled=false,turnstileToken='',turnstileWidget=null,requestNumber=0;const verification=document.querySelector('#ai-verification');
siteSettings.then(s=>s.backend?fetch(new URL('api/status',document.baseURI)):Promise.reject()).then(r=>r.ok?r.json():Promise.reject()).then(s=>{aiEnabled=s.aiEnabled;$('#question').placeholder=aiEnabled?'Ask my AI guide about my work…':'Ask about my experience, projects, or skills…';if(s.turnstileSiteKey){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=()=>{turnstileWidget=window.turnstile.render(verification,{sitekey:s.turnstileSiteKey,theme:'dark',callback:t=>{turnstileToken=t},'expired-callback':()=>{turnstileToken=''}})};script.onerror=()=>{aiEnabled=false};document.head.append(script)}}).catch(()=>{});
async function ask(q){q=q.trim();if(!q)return;if(!aiEnabled){localAsk(q);return}const current=++requestNumber;const a=$('#answer');a.hidden=false;const close=document.createElement('button');close.textContent='Close';close.type='button';close.onclick=()=>a.hidden=true;const text=document.createElement('span');text.textContent='Thinking through your question…';a.replaceChildren(close,text);a.setAttribute('aria-busy','true');const button=$('#ask-form button');button.disabled=true;try{const r=await fetch(new URL('api/chat',document.baseURI),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,turnstileToken}),signal:AbortSignal.timeout(30000)});const data=await r.json();if(current!==requestNumber)return;if(!r.ok){text.textContent=data.error||'The AI guide is unavailable.';const fallback=document.createElement('button');fallback.textContent='Use resume guide';fallback.onclick=()=>localAsk(q);a.append(fallback);return}text.textContent=data.answer;const note=document.createElement('small');note.textContent='AI GUIDE · GROUNDED IN RESUME & PUBLIC PROJECTS';note.style.cssText='display:block;font-size:8px;letter-spacing:1px;margin-top:14px;color:#9fb4c9';a.append(note)}catch{if(current!==requestNumber)return;text.textContent='The AI guide is unavailable. ';const fallback=document.createElement('button');fallback.textContent='Use resume guide';fallback.onclick=()=>localAsk(q);a.append(fallback)}finally{button.disabled=false;a.setAttribute('aria-busy','false');turnstileToken='';if(turnstileWidget!==null)window.turnstile.reset(turnstileWidget)}}
let scrollQueued=false;function scrollScene(){scrollQueued=false;const track=$('.entry-track');const rect=track.getBoundingClientRect();const distance=Math.max(1,rect.height-innerHeight);const p=Math.max(0,Math.min(1,-rect.top/distance));if(motionOff){$('.scroll-identity').style.opacity=0;return}$('#studio').style.transform=`scale(${1.04+p*.25}) translate(${-p*7}%,${p*2}%)`;$('.hero-copy').style.opacity=String(Math.max(0,1-p*2.5));$('.hero-copy').style.transform=`translateY(${-p*90}px)`;$('.scroll-identity').style.opacity=String(Math.max(0,Math.min(1,(p-.25)*2)));$('.scroll-identity').style.transform=`translateY(${(1-p)*60}px)`;$('.hotspots').style.opacity=String(1-p);$('.scene-label').style.opacity=String(1-p)}window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(scrollScene)}},{passive:true});window.addEventListener('motionchange',()=>{if(motionOff){$('.hero-copy').style.opacity='1';$('.hero-copy').style.transform='none';$('#studio').style.transform='none';$('.scroll-identity').style.opacity=0}else scrollScene()});scrollScene();
